// Forja standalone migrations: prepares the database of an exported project and applies its
// migrations once, in order. Generated by "Exportar para producción"; re-export to update.
//
// - The app role (APP_DB_PASSWORD) uses the public schema.
// - Each component with its own database gets a schema and a login role
//   (DB_PASSWORD_<SCHEMA>) with rights on that schema only.
// - public.forja_jobs is the job queue every service shares.
// - Applied migrations are recorded in public._forja_migrations with their checksum, the same
//   ledger Forja uses: a changed or deleted applied migration stops the run.
import { readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import path from "node:path";
import { fileURLToPath } from "node:url";
import pg from "pg";

const here = path.dirname(fileURLToPath(import.meta.url));
const plan = JSON.parse(readFileSync(path.join(here, "plan.json"), "utf8"));
const client = new pg.Client({ connectionString: process.env.DATABASE_URL });

const ident = (name) => {
  if (!/^[a-z_][a-z0-9_]*$/.test(name)) throw new Error(`Identificador no válido: ${name}`);
  return `"${name}"`;
};
const literal = (value) => `'${String(value).replaceAll("'", "''")}'`;
const password = (variable) => {
  const value = process.env[variable];
  if (!value) throw new Error(`Define ${variable} (contraseña de la base de datos).`);
  return value;
};
const checksum = (sql) => createHash("sha256").update(sql).digest("hex");
const version = (file) => BigInt(/(?:^|[/:])(\d+)_[^/:]*$/.exec(file)[1]);
// Same ledger keys as Forja: the app's migrations by path, a component's by schema + file name.
const ledgerName = (m) => (m.schema ? `${m.schema}:migrations/${m.path.slice(m.path.lastIndexOf("/") + 1)}` : m.path);
const ledgerSchema = (name) => /^([a-z][a-z0-9_]*):migrations\//.exec(name)?.[1];

async function ensureRole(role, variable) {
  const exists = (await client.query("select 1 from pg_roles where rolname = $1", [role])).rowCount;
  await client.query(`${exists ? "alter" : "create"} role ${ident(role)} with login password ${literal(password(variable))}`);
}

async function main() {
  await client.connect();
  await client.query(`
    create table if not exists public._forja_users (
      id text primary key, email text not null unique, name text, role text not null default 'user',
      password_hash text, failed_logins integer not null default 0, locked_until timestamptz,
      created_at timestamptz not null default now());
    create table if not exists public._forja_migrations (
      migration_name text primary key, checksum text not null, applied_at timestamptz not null default now());
    create table if not exists public.forja_jobs (
      id bigserial primary key, name text not null, payload jsonb, run_at timestamptz not null default now(),
      status text not null default 'queued', attempts integer not null default 0, locked_until timestamptz,
      last_error text, dedupe text unique, created_at timestamptz not null default now());
    create index if not exists forja_jobs_ready on public.forja_jobs (name, run_at) where status in ('queued', 'running');
  `);

  await ensureRole(plan.appRole.role, plan.appRole.passwordEnv);
  for (const scope of plan.schemas) {
    await ensureRole(scope.role, scope.passwordEnv);
    const s = ident(scope.schema), r = ident(scope.role);
    await client.query(`create schema if not exists ${s};
      grant usage, create on schema ${s} to ${r};
      alter default privileges in schema ${s} grant all on tables to ${r};
      alter default privileges in schema ${s} grant all on sequences to ${r};`);
  }

  const applied = new Map((await client.query("select migration_name, checksum from public._forja_migrations")).rows.map((r) => [r.migration_name, r.checksum]));
  const byName = new Map(plan.migrations.map((m) => [ledgerName(m), m]));
  const declared = new Set(plan.schemas.map((s) => s.schema));
  const retired = new Set();
  for (const [name, hash] of applied) {
    const migration = byName.get(name);
    const schema = ledgerSchema(name);
    if (!migration) {
      // A schema no component declares any more is retired: kept with its data, no longer gating.
      if (schema && !declared.has(schema)) { retired.add(schema); continue; }
      throw new Error(`La migración aplicada ${name} fue eliminada o renombrada.`);
    }
    if (checksum(readFileSync(path.join(here, "migrations", migration.path), "utf8")) !== hash) throw new Error(`La migración aplicada ${migration.path} fue modificada.`);
  }
  const latest = new Map();
  for (const name of applied.keys()) {
    const schema = ledgerSchema(name);
    if (schema && retired.has(schema)) continue;
    const track = schema ?? "";
    if (version(name) > (latest.get(track) ?? 0n)) latest.set(track, version(name));
  }
  const done = [];
  for (const migration of plan.migrations) {
    if (applied.has(ledgerName(migration))) continue;
    const track = migration.schema ?? "";
    if (version(migration.path) <= (latest.get(track) ?? 0n)) throw new Error(`${migration.path}: su orden debe ser posterior a las migraciones ya aplicadas.`);
    const sql = readFileSync(path.join(here, "migrations", migration.path), "utf8");
    await client.query("begin");
    try {
      if (migration.schema) await client.query(`set local search_path to ${ident(migration.schema)}, public`);
      await client.query(sql);
      await client.query("insert into public._forja_migrations (migration_name, checksum) values ($1, $2)", [ledgerName(migration), checksum(sql)]);
      await client.query("commit");
    } catch (error) {
      await client.query("rollback");
      throw new Error(`${migration.path}: ${error.message}`);
    }
    latest.set(track, version(migration.path));
    done.push(migration.path);
  }

  // Rights after the tables exist: the app role on public, each component role on its schema,
  // everyone on the shared job queue.
  const app = ident(plan.appRole.role);
  await client.query(`grant usage on schema public to ${app};
    grant select, insert, update, delete on all tables in schema public to ${app};
    grant usage, select, update on all sequences in schema public to ${app};
    alter default privileges in schema public grant select, insert, update, delete on tables to ${app};
    alter default privileges in schema public grant usage, select, update on sequences to ${app};`);
  for (const scope of plan.schemas) {
    const s = ident(scope.schema), r = ident(scope.role);
    await client.query(`grant all on all tables in schema ${s} to ${r};
      grant all on all sequences in schema ${s} to ${r};
      grant usage on schema public to ${r};
      grant select, insert, update, delete on public.forja_jobs to ${r};
      grant usage, select on sequence public.forja_jobs_id_seq to ${r};`);
  }
  console.log(done.length ? `Migraciones aplicadas:\n${done.join("\n")}` : "La base de datos ya estaba al día.");
  for (const schema of retired) console.log(`Esquema retirado (se conserva con sus datos; ningún servicio lo usa): ${schema}`);
  await client.end();
}

main().catch(async (error) => {
  console.error(error.message);
  await client.end().catch(() => {});
  process.exit(1);
});
